import { loadFromGitHub } from 'gowm';

// Load goxios module from wasm-modules-repository
const goxios = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
  path: 'goxios-wasm',
  name: 'goxios-wasm',
  branch: 'master'
});

// Configure module
goxios.call('setSilentMode', true);

// Set global default configuration
const defaultConfig = JSON.stringify({
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
    'User-Agent': 'MyApp/1.0'
  }
});
goxios.call('setDefaults', defaultConfig);

// Make GET request with error handling
const response = goxios.call('get', 'https://jsonplaceholder.typicode.com/posts/1');
if (response.error) {
  console.error('GET request failed:', response.error);
} else {
  console.log('Status:', response.status);
  console.log('Data:', JSON.parse(response.data));
  console.log('Headers:', response.headers);
}

// Create new post
const postData = JSON.stringify({
  title: 'New Post',
  body: 'This is the post content',
  userId: 1
});

const postResponse = goxios.call('post', 'https://jsonplaceholder.typicode.com/posts', postData);
if (postResponse.error) {
  console.error('POST failed:', postResponse.error);
} else {
  const createdPost = JSON.parse(postResponse.data);
  console.log('Created post ID:', createdPost.id);
  console.log('Response status:', postResponse.status);
}

// Update post with PUT
const updateData = JSON.stringify({
  id: 1,
  title: 'Updated Post Title',
  body: 'Updated content',
  userId: 1
});

const putResponse = goxios.call('put', 'https://jsonplaceholder.typicode.com/posts/1', updateData);
if (putResponse.error) {
  console.error('PUT failed:', putResponse.error);
} else {
  console.log('Updated successfully:', JSON.parse(putResponse.data));
}

// Comprehensive HTTP client with robust error handling
import { loadFromGitHub } from 'gowm';

class ApiClient {
  constructor() {
    this.goxios = null;
    this.ready = false;
    this.requestCount = 0;
    this.loadModule();
  }

  async loadModule() {
    try {
      this.goxios = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
        path: 'goxios-wasm',
              name: 'goxios-wasm',
        branch: 'master'
      });

      // Configure for production use
      this.goxios.call('setSilentMode', true);

      // Set default configuration
      const defaultConfig = JSON.stringify({
        timeout: 10000,
        headers: { 
          'Content-Type': 'application/json',
          'User-Agent': 'Goxios-WASM-Client/1.0'
        }
      });
      this.goxios.call('setDefaults', defaultConfig);

      // Get available functions
      const functions = this.goxios.call('getAvailableFunctions');
      console.log('Available HTTP functions:', functions);

      this.ready = true;
    } catch (error) {
      console.error('Failed to load Goxios module:', error);
    }
  }

  // Safe HTTP request wrapper
  makeRequest(method, url, data = null, config = null) {
    if (!this.ready) {
      throw new Error('Goxios module not ready');
    }

    this.requestCount++;
    console.log(`[Request ${this.requestCount}] ${method.toUpperCase()} ${url}`);

    let response;
    if (data && config) {
      response = this.goxios.call(method, url, data, config);
    } else if (data) {
      response = this.goxios.call(method, url, data);
    } else if (config) {
      response = this.goxios.call(method, url, config);
    } else {
      response = this.goxios.call(method, url);
    }

    if (response.error) {
      throw new Error(`HTTP ${method.toUpperCase()} failed: ${response.error}`);
    }

    return response;
  }

  // REST API methods
  get(url, config = null) {
    return this.makeRequest('get', url, null, config);
  }

  post(url, data, config = null) {
    return this.makeRequest('post', url, data, config);
  }

  put(url, data, config = null) {
    return this.makeRequest('put', url, data, config);
  }

  delete(url, config = null) {
    return this.makeRequest('delete', url, null, config);
  }

  patch(url, data, config = null) {
    return this.makeRequest('patch', url, data, config);
  }

  // High-level API operations
  async fetchPosts(limit = 10) {
    const response = this.get('https://jsonplaceholder.typicode.com/posts');
    const posts = JSON.parse(response.data);
    return posts.slice(0, limit);
  }

  async createPost(title, body, userId = 1) {
    const postData = JSON.stringify({ title, body, userId });
    const response = this.post('https://jsonplaceholder.typicode.com/posts', postData);
    return JSON.parse(response.data);
  }

  async updatePost(id, updates) {
    const updateData = JSON.stringify(updates);
    const response = this.put(`https://jsonplaceholder.typicode.com/posts/${id}`, updateData);
    return JSON.parse(response.data);
  }

  async deletePost(id) {
    const response = this.delete(`https://jsonplaceholder.typicode.com/posts/${id}`);
    return response.status === 200;
  }

  // Statistics and monitoring
  getStats() {
    return {
      ready: this.ready,
      requestCount: this.requestCount,
      defaults: this.ready ? this.goxios.call('getDefaults') : null
    };
  }
}

// Usage example
const apiClient = new ApiClient();

// Wait for module to load
setTimeout(async () => {
  if (apiClient.ready) {
    try {
      // Fetch posts
      console.log('Fetching posts...');
      const posts = await apiClient.fetchPosts(5);
      console.log('Posts fetched:', posts.length);
      posts.forEach(post => {
        console.log(`- ${post.title} (User ${post.userId})`);
      });

      // Create new post
      console.log('\nCreating new post...');
      const newPost = await apiClient.createPost(
        'Test Post from Goxios WASM',
        'This post was created using the Goxios WASM module with GoWM.',
        1
      );
      console.log('Post created:', {
        id: newPost.id,
        title: newPost.title,
        userId: newPost.userId
      });

      // Update post
      console.log('\nUpdating post...');
      const updatedPost = await apiClient.updatePost(1, {
        title: 'Updated Title',
        body: 'Updated content'
      });
      console.log('Post updated:', updatedPost.title);

      // Statistics
      console.log('\nAPI Client Stats:', apiClient.getStats());

    } catch (error) {
      console.error('API operation failed:', error.message);
    }
  }
}, 1000);

// Custom request with full configuration
