}

// Helper function for consistent HTTP error handling
function handleHttpResponse(response, successCallback, errorCallback) {
  if (response.error) {
    errorCallback(response.error, response.status || null);
  } else {
    successCallback(response.data, response.status, response.headers);
  }
}

// Usage examples with different request types
const requests = [
  { method: 'get', url: 'https://jsonplaceholder.typicode.com/posts/1' },
  { method: 'get', url: 'https://invalid-domain-that-does-not-exist.com' }, // Will fail
  { method: 'post', url: 'https://jsonplaceholder.typicode.com/posts', data: JSON.stringify({title: 'Test'}) },
  { method: 'delete', url: 'https://jsonplaceholder.typicode.com/posts/1' }
];

requests.forEach((req, index) => {
  const response = req.data ? 
    goxios.call(req.method, req.url, req.data) : 
    goxios.call(req.method, req.url);

  handleHttpResponse(
    response,
    (data, status, headers) => {
      console.log(`Request ${index + 1} (${req.method.toUpperCase()}) success:`);
      console.log(`  Status: ${status}`);
      console.log(`  Data: ${typeof data === 'string' ? data.substring(0, 100) + '...' : data}`);
    },
    (error, status) => {
      console.error(`Request ${index + 1} (${req.method.toUpperCase()}) failed:`);
      console.error(`  Error: ${error}`);
      if (status) console.error(`  Status: ${status}`);
    }
  );
});

